const skillTypes = ['Passive', 'Skill 1', 'Skill 2', 'Ultimate'];
const genericDescription = (name: string, hero: string, role: string, i: number): Localized => ({
  en: `${name} is part of ${hero}’s ${role.toLowerCase()} toolkit. ${i === 0 ? 'This passive complements the hero’s core combat style.' : i === 3 ? 'Save this key ability for a coordinated engage or a decisive team fight.' : 'Use it to manage spacing, control the lane, and create an opening for your team.'} Practice timing in training mode; exact values vary by patch.`,
  fa: `«${name}» بخشی از جعبه‌ابزار ${hero} است. ${i === 0 ? 'این پسیو مکمل سبک اصلی مبارزهٔ هیرو است.' : i === 3 ? 'این مهارت کلیدی را برای ورود هماهنگ یا یک تیم‌فایت سرنوشت‌ساز نگه دارید.' : 'از آن برای مدیریت فاصله، کنترل لاین و ایجاد فرصت برای تیم استفاده کنید.'} زمان‌بندی را در حالت تمرین تکرار کنید؛ مقادیر دقیق بسته به پچ تغییر می‌کند.`,
});

const roster = rosterJson as unknown as { heroes: Hero[]; items: Item[]; builds: Build[] };
const rosterById = new Map(roster.heroes.map((h) => [h.hero_id, h]));
const slug = (s: string) =>
  s
    .toLowerCase()
    .replace(/['’.]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

export const curatedHeroes: Hero[] = entries.map(
  ([
    id,
    name,
    nameFa,
    title,
    role,
    lane,
    tier,
    difficulty,
    win,
    pick,
    color,
    counters,
    lore,
    base,
    names,
  ]) => {
    const imported = rosterById.get(id);
    const skills: Skill[] = names.map((n, i) => {
      const fromSource =
        imported?.skills.find((s) => s.slug === slug(n)) ||
        imported?.skills.find((s) => s.skill_type === skillTypes[i]);
      return {
        skill_name: L(n, n),
        skill_type: skillTypes[i],
        cooldown: null,
        mana_cost: null,
        description:
          descriptions[id]?.[i] || fromSource?.description || genericDescription(n, name, role, i),
        damage_type:
          fromSource?.damage_type || (role === 'Mage' || role === 'Support' ? 'Magic' : 'Physical'),
        slug: slug(n),
        icon_url: fromSource?.icon_url || '',
        tags: fromSource?.tags || [],
        notes: fromSource?.notes,
      };
    });
    const mergedCounters = [...new Set([...counters, ...(imported?.counters || [])])].slice(0, 4);
    return {
      hero_id: id,
      name,
      name_fa: nameFa,
      title,
      role,
      lane,
      tier,
      difficulty,
      win_rate: win,
      pick_rate: pick,
      color,
      counters: mergedCounters,
      lore,
      base_stats: base,
      image_url: `/images/heroes/${id}.webp`,
      featured: id === 'ling',
      best_builds: [`${id}-balanced`],
      skills,
      quality: {
        stats: 'editorial',
        skills: descriptions[id] ? 'editorial' : imported ? 'source' : 'editorial',
        lane: 'editorial',
        tier: 'editorial',
      },
      source_url: imported?.source_url,
      patch_version: imported?.patch_version || '',
      last_verified: imported?.last_verified || '2026-01-15',
    };
  },
);

